#include <stdlib.h>

#define MAXV 26
#define MAXN 100

int adj[MAXV][MAXV];
int dist[MAXV];
int queue[MAXV];
int front, rear;

void bfs(int start, int n) {
    for (int i = 0; i < n; i++) dist[i] = -1;
    front = rear = 0;
    dist[start] = 0;
    queue[rear++] = start;
    while (front < rear) {
        int u = queue[front++];
        for (int v = 0; v < n; v++) {
            if (adj[u][v] && dist[v] == -1) {
                dist[v] = dist[u] + 1;
                queue[rear++] = v;
            }
        }
    }
}

