#define MAXH 205
#define MAXW 205
#define INF 1000000000

int main(void) {
    int H, W;
    char s, t;
    static char g[MAXH][MAXW + 5];

    if (scanf("%d %d", &H, &W) != 2) return 0;
    scanf(" %c %c", &s, &t);

    for (int i = 0; i < H; i++) {
        scanf("%s", g[i]);
    }

    int pos[26][2];
    for (int i = 0; i < 26; i++) pos[i][0] = pos[i][1] = -1;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if ('A' <= g[i][j] && g[i][j] <= 'Z') {
                int id = g[i][j] - 'A';
                pos[id][0] = i;
                pos[id][1] = j;
            }
        }
    }

    static int dist[26][26];
    for (int i = 0; i < 26; i++) {
        for (int j = 0; j < 26; j++) {
            dist[i][j] = (i == j ? 0 : INF);
        }
    }

    /* Detect edges from each vertex by looking outside its surrounding o-ring.
       Vertex center at (r,c):
       horizontal edge starts at (r, c+2) or (r, c-2)
       vertical edge starts at (r+2, c) or (r-2, c)
    */
    for (int v = 0; v < 26; v++) {
        if (pos[v][0] == -1) continue;
        int r = pos[v][0], c = pos[v][1];

        /* Right */
        if (c + 2 < W && g[r][c + 2] == '-') {
            int k = c + 2;
            while (k < W && g[r][k] == '-') k++;
            if (k < W && 'A' <= g[r][k] && g[r][k] <= 'Z') {
                int u = g[r][k] - 'A';
                dist[v][u] = dist[u][v] = 1;
            }
        }

        /* Left */
        if (c - 2 >= 0 && g[r][c - 2] == '-') {
            int k = c - 2;
            while (k >= 0 && g[r][k] == '-') k--;
            if (k >= 0 && 'A' <= g[r][k] && g[r][k] <= 'Z') {
                int u = g[r][k] - 'A';
                dist[v][u] = dist[u][v] = 1;
            }
        }

        /* Down */
        if (r + 2 < H && g[r + 2][c] == '|') {
            int k = r + 2;
            while (k < H && g[k][c] == '|') k++;
            if (k < H && 'A' <= g[k][c] && g[k][c] <= 'Z') {
                int u = g[k][c] - 'A';
                dist[v][u] = dist[u][v] = 1;
            }
        }

        /* Up */
        if (r - 2 >= 0 && g[r - 2][c] == '|') {
            int k = r - 2;
            while (k >= 0 && g[k][c] == '|') k--;
            if (k >= 0 && 'A' <= g[k][c] && g[k][c] <= 'Z') {
                int u = g[k][c] - 'A';
                dist[v][u] = dist[u][v] = 1;
            }
        }
    }

    for (int k = 0; k < 26; k++) {
        for (int i = 0; i < 26; i++) {
            if (dist[i][k] == INF) continue;
            for (int j = 0; j < 26; j++) {
                if (dist[k][j] == INF) continue;
                if (dist[i][j] > dist[i][k] + dist[k][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
    }

    int ans = dist[s - 'A'][t - 'A'];
    printf("%d\n", ans);
    return 0;
}

