                for (int di = -1; di <= 1; di++) {
                    for (int dj = -1; dj <= 1; dj++) {
                        if (di == 0 && dj == 0) continue;
                        int ni = i + di, nj = j + dj;
                        if (ni < 0 || ni >= H || nj < 0 || nj >= W || grid[ni][nj] != 'o') {
                            valid = false;
                            break;
                        }
                    }
                    if (!valid) break;
                }
                if (valid) {
                    vertices[grid[i][j]] = {i, j};
                }
            }
        }
    }

    // Build adjacency list
    map<char, vector<pair<char,int>>> adj;
    for (auto& [v, pos] : vertices) {
        int r = pos.first, c = pos.second;

        // Check horizontal edges (to the right)
        for (int j = c + 2; j < W; j++) {
            if (grid[r][j] == '-') continue;
            if (isupper(grid[r][j]) && grid[r][j] != v) {
                // Check if there's a direct horizontal path
                bool valid = true;
                for (int k = c + 2; k < j; k++) {
                    if (grid[r][k] != '-') {
                        valid = false;
                        break;
                    }
                }
                if (valid) {
                    int dist = (j - c) / 2;
                    adj[v].push_back({grid[r][j], dist});
                    adj[grid[r][j]].push_back({v, dist});
                }
                break;
            }
            if (grid[r][j] != '-') break;
        }

        // Check vertical edges (downward)
        for (int i = r + 2; i < H; i++) {
            if (grid[i][c] == '|') continue;
            if (isupper(grid[i][c]) && grid[i][c] != v) {
                // Check if there's a direct vertical path
                bool valid = true;
                for (int k = r + 2; k < i; k++) {
                    if (grid[k][c] != '|') {
                        valid = false;
                        break;
                    }
                }
                if (valid) {
                    int dist = (i - r) / 2;
                    adj[v].push_back({grid[i][c], dist});
                    adj[grid[i][c]].push_back({v, dist});
                }
                break;
            }
            if (grid[i][c] != '|') break;
        }
    }

    // Dijkstra's algorithm
    map<char, int> dist;
    for (auto& [v, _] : vertices) {
        dist[v] = INT_MAX;
    }
    dist[s] = 0;

    priority_queue<pair<int,char>, vector<pair<int,char>>, greater<pair<int,char>>> pq;
    pq.push({0, s});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();

        if (d != dist[u]) continue;
        if (u == t) break;

        for (auto& [v, w] : adj[u]) {
            if (dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }

    cout << dist[t] << '\n';

    return 0;
