int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    if (!(cin >> H >> W)) return 0;

    char S, T;
    cin >> S >> T;
    string dummy;
    getline(cin, dummy); // consume endline

    vector<string> g(H);
    for (int i = 0; i < H; ++i) getline(cin, g[i]);

    // Map each vertex letter to its center position.
    // A vertex is an uppercase letter whose 8 neighbors are all 'o'.
    map<char, pair<int,int>> pos;
    for (int i = 1; i + 1 < H; ++i) {
        for (int j = 1; j + 1 < W; ++j) {
            if ('A' <= g[i][j] && g[i][j] <= 'Z') {
                bool ok = true;
                for (int di = -1; di <= 1; ++di) {
                    for (int dj = -1; dj <= 1; ++dj) {
                        if (di == 0 && dj == 0) continue;
                        if (g[i + di][j + dj] != 'o') ok = false;
                    }
                }
                if (ok) pos[g[i][j]] = {i, j};
            }
        }
    }

    const int INF = 1e9;
    map<char, int> dist;
    for (auto &kv : pos) dist[kv.first] = INF;

    queue<char> q;
    dist[S] = 0;
    q.push(S);

    auto findVertexAt = [&](int x, int y) -> char {
        for (auto &kv : pos) {
            if (kv.second.first == x && kv.second.second == y) return kv.first;
        }
        return 0;
    };

    // From a vertex center, possible edge starts are:
    // left/right: same row, columns j-2 / j+2 with '-'
    // up/down: same col, rows i-2 / i+2 with '|'
    while (!q.empty()) {
        char u = q.front(); q.pop();
        auto [x, y] = pos[u];

        vector<char> neighbors;

        // Left
        if (y - 2 >= 0 && g[x][y - 2] == '-') {
            int ny = y - 2;
            while (ny >= 0 && g[x][ny] == '-') ny--;
            if (ny >= 0 && 'A' <= g[x][ny] && g[x][ny] <= 'Z') {
                char v = findVertexAt(x, ny);
                if (v) neighbors.push_back(v);
            }
        }
        // Right
        if (y + 2 < W && g[x][y + 2] == '-') {
            int ny = y + 2;
            while (ny < W && g[x][ny] == '-') ny++;
            if (ny < W && 'A' <= g[x][ny] && g[x][ny] <= 'Z') {
                char v = findVertexAt(x, ny);
                if (v) neighbors.push_back(v);
            }
        }
        // Up
        if (x - 2 >= 0 && g[x - 2][y] == '|') {
            int nx = x - 2;
            while (nx >= 0 && g[nx][y] == '|') nx--;
            if (nx >= 0 && 'A' <= g[nx][y] && g[nx][y] <= 'Z') {
                char v = findVertexAt(nx, y);
                if (v) neighbors.push_back(v);
            }
        }
        // Down
        if (x + 2 < H && g[x + 2][y] == '|') {
            int nx = x + 2;
            while (nx < H && g[nx][y] == '|') nx++;
            if (nx < H && 'A' <= g[nx][y] && g[nx][y] <= 'Z') {
                char v = findVertexAt(nx, y);
                if (v) neighbors.push_back(v);
            }
        }

        for (char v : neighbors) {
            if (dist[v] > dist[u] + 1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }

    cout << dist[T] << '\n';
    return 0;
}

