                    graph.get(c).put(neighbor, dist);
                    graph.get(neighbor).put(c, dist);
                }
            }
            // Check vertical edges
            for (int nx = x + 1; nx < H && grid[nx][y] == '|'; nx++);
            if (x + 1 < H && grid[x + 1][y] == '|') {
                int ex = x + 1;
                while (ex < H && grid[ex][y] == '|') ex++;
                if (ex < H && grid[ex][y] >= 'A' && grid[ex][y] <= 'Z') {
                    char neighbor = grid[ex][y];
                    int dist = ex - x - 1;
                    graph.get(c).put(neighbor, dist);
                    graph.get(neighbor).put(c, dist);
                }
            }
        }

        // Dijkstra
        Map<Character, Integer> dist = new HashMap<>();
        for (char c : vertexPos.keySet()) dist.put(c, Integer.MAX_VALUE);
        dist.put(s, 0);

        PriorityQueue<Pair> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a.d));
        pq.add(new Pair(s, 0));

        while (!pq.isEmpty()) {
            Pair cur = pq.poll();
            char u = cur.v;
            int d = cur.d;
            if (d != dist.get(u)) continue;
            if (u == t) break;
            for (Map.Entry<Character, Integer> e : graph.get(u).entrySet()) {
                char v = e.getKey();
                int w = e.getValue();
                if (dist.get(v) > d + w) {
                    dist.put(v, d + w);
                    pq.add(new Pair(v, d + w));
                }
            }
        }

        System.out.println(dist.get(t));
    }

    static class Pair {
        char v;
        int d;
        Pair(char v, int d) {
            this.v = v;
            this.d = d;
        }
    }
