                if (c >= 'A' && c <= 'Z') {
                    id.put(c, pos.size());
                    pos.add(new int[]{i, j});
                }
            }
        }

        int n = pos.size();
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());

        // Detect horizontal edges: A---B on same row
        for (int i = 0; i < n; i++) {
            int r = pos.get(i)[0];
            int c = pos.get(i)[1];

            int y = c + 2; // skip the surrounding 'o'
            boolean seenDash = false;
            while (y < W && g[r][y] == '-') {
                seenDash = true;
                y++;
            }
            if (seenDash && y + 1 < W && g[r][y] == 'o' && g[r][y + 1] >= 'A' && g[r][y + 1] <= 'Z') {
                char to = g[r][y + 1];
                Integer j = id.get(to);
                if (j != null) {
                    adj.get(i).add(j);
                    adj.get(j).add(i);
                }
            }

            // Detect vertical edges: A with | below
            int x = r + 2; // skip surrounding 'o'
            boolean seenPipe = false;
            while (x < H && g[x][c] == '|') {
                seenPipe = true;
                x++;
            }
            if (seenPipe && x + 1 < H && g[x][c] == 'o' && g[x + 1][c] >= 'A' && g[x + 1][c] <= 'Z') {
                char to = g[x + 1][c];
                Integer j = id.get(to);
                if (j != null) {
                    adj.get(i).add(j);
                    adj.get(j).add(i);
                }
            }
        }

        int start = id.get(s);
        int goal = id.get(t);

        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        dist[start] = 0;
        q.add(start);

        while (!q.isEmpty()) {
            int v = q.poll();
            if (v == goal) break;
            for (int to : adj.get(v)) {
                if (dist[to] == -1) {
                    dist[to] = dist[v] + 1;
                    q.add(to);
                }
            }
        }

        System.out.println(dist[goal]);
    }
}

