import sys
from collections import deque

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    H, W = map(int, data[0].split())
    s, t = data[1].split()
    grid = data[2:2+H]

    # Find all vertices (uppercase letters)
    pos = {}
    for i in range(H):
        row = grid[i]
        for j, ch in enumerate(row):
            if 'A' <= ch <= 'Z':
                pos[ch] = (i, j)

    # Build graph by checking possible horizontal/vertical edges
    graph = {v: [] for v in pos}

    # Horizontal edges: A---B
    for v, (x, y) in pos.items():
        ny = y + 1
        while ny < W and grid[x][ny] == '-':
            ny += 1
        if ny < W and 'A' <= grid[x][ny] <= 'Z':
            u = grid[x][ny]
            graph[v].append(u)

    # Vertical edges: A
    #                 |
    #                 |
    #                 B
    for v, (x, y) in pos.items():
        nx = x + 1
        while nx < H and grid[nx][y] == '|':
            nx += 1
        if nx < H and 'A' <= grid[nx][y] <= 'Z':
            u = grid[nx][y]
            graph[v].append(u)

    # BFS shortest path
    dist = {v: -1 for v in pos}
    q = deque([s])
    dist[s] = 0

    while q:
        cur = q.popleft()
        if cur == t:
            break
        for nxt in graph[cur]:
            if dist[nxt] == -1:
                dist[nxt] = dist[cur] + 1
                q.append(nxt)

    print(dist[t])

